const ledgers = { source: null, destination: null };
for (const item of $input.all()) {
  const { ledger, sales } = item.json;
  if (!Object.hasOwn(ledgers, ledger) || ledgers[ledger] !== null || !Array.isArray(sales)) {
    throw new Error('Expected one source export and one destination export');
  }
  ledgers[ledger] = sales;
}

const groups = new Map();
for (const [ledger, sales] of Object.entries(ledgers)) {
  if (sales === null) throw new Error('Missing ' + ledger + ' export');
  for (const row of sales) {
    if (typeof row.sale_id !== 'string' || !row.sale_id.trim() ||
        !Number.isSafeInteger(row.amount_minor) || !/^[A-Z]{3}$/.test(row.currency) ||
        typeof row.allow_follow_up !== 'boolean') {
      throw new Error('Invalid row in ' + ledger + ' export');
    }
    if (!groups.has(row.sale_id)) groups.set(row.sale_id, { source: [], destination: [] });
    groups.get(row.sale_id)[ledger].push(row);
  }
}

return [...groups.keys()].sort().map(sale_id => {
  const { source, destination } = groups.get(sale_id);
  const issues = [];
  if (source.length === 0) issues.push('unexpected_destination_sale');
  if (destination.length === 0) issues.push('missing_destination_sale');
  if (source.length > 1) issues.push('duplicate_source_id');
  if (destination.length > 1) issues.push('duplicate_destination_id');
  if (source.length === 1 && destination.length === 1) {
    if (source[0].amount_minor !== destination[0].amount_minor) issues.push('amount_mismatch');
    if (source[0].currency !== destination[0].currency) issues.push('currency_mismatch');
    if (source[0].allow_follow_up !== destination[0].allow_follow_up) issues.push('consent_mismatch');
  }
  const needs_review = issues.length > 0;
  const follow_up_allowed = !needs_review && source[0].allow_follow_up && destination[0].allow_follow_up;
  return { json: { sale_id, needs_review, issues, follow_up_allowed, source, destination } };
});
